private val Ink = SolidColor(Color.Black)
private const val StrokeWidth = 1.7f

private fun line(vararg paths: String, mirror: Boolean = false) =
    icon(stroke = paths.joinToString(""), fill = null, mirror = mirror)

private fun solid(path: String) = icon(stroke = null, fill = path, mirror = false)

private fun mixed(stroke: String, fill: String) = icon(stroke, fill, mirror = false)

private fun icon(stroke: String?, fill: String?, mirror: Boolean) = lazy(LazyThreadSafetyMode.PUBLICATION) {
    ImageVector.Builder(
        name = "AppIcon",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = mirror
    ).apply {
        fill?.let { addPath(addPathNodes(it), pathFillType = PathFillType.EvenOdd, fill = Ink) }
        stroke?.let {
            addPath(
                addPathNodes(it),
                stroke = Ink,
                strokeLineWidth = StrokeWidth,
                strokeLineCap = StrokeCap.Round,
                strokeLineJoin = StrokeJoin.Round
            )
        }
    }.build()
}
